user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0 .. i + 1])
{
    var maxValue := numbers[0];
    var n := |numbers|;
    var res := new int[n];

    // Initialize the first element of the result
    res[0] := maxValue;

    // Compute rolling maximum
    var i := 1;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> res[j] == Max(numbers[0 .. j + 1])
        invariant maxValue == Max(numbers[0 .. i])
    {
        if numbers[i] > maxValue {
            maxValue := numbers[i];
        }
        res[i] := maxValue;
        i := i + 1;
    }

    result := res;
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

